// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev The PriceFeed's launch policy (1-hour lifetime, 2,000 bps cap) with an attester whose key this
/// test holds and no pinned question, so only the epoch bound is exercised.
contract HeldFeed is SwarmFeed {
    constructor(address attester_, address relayer_) SwarmFeed(attester_, relayer_, 1, 3, 1 hours, 2_000) {}
}

/// @notice FINDING: the stale base is earned by the age of the signed `issuedAt`, not by silence of the
/// feed. `_allowanceNow` measures "whole periods stale" from `_updatedAt`, which `_accept` sets to the
/// attestation's signed issue time, while the epoch is measured from the block the value was relayed in.
/// `submitAttestation` accepts an issuedAt up to one lifetime old, so a buyer who holds every answer for
/// most of an hour before relaying it opens every epoch on a value the feed believes has been stale for
/// a whole hour, and takes STALE_DEVIATION_MULTIPLE x the cap (40%) at every step, one step an hour.
///
/// The NatSpec (SwarmFeed.sol:27-30, 47-49, 410-414) says the stale base is "earned by silence, never by
/// timing" and that "a feed anyone keeps alive moves at most the cap per hour however it is driven".
/// This test keeps the feed alive with one relay an hour and moves it 1.2 x 1.4^3 = 3.29x in four hours
/// where the cap per hour allows 1.2^4 = 2.07x. It fails on the committed code and passes once the
/// allowance's staleness is measured from the later of the signed time and the epoch's open (the relay).
contract StaleBaseByHeldAnswerTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    uint256 private constant V = 3_550_000 gwei; // ~0.00355 ETH per IMD, the live figure
    uint256 private constant HOLD = 1 hours - 5 minutes; // the panel answers minutes after the window closes
    HeldFeed private feed;
    uint256 private nonce;

    function setUp() public {
        vm.chainId(1);
        vm.warp(10 days);
        vm.roll(1_000_000);
        feed = new HeldFeed(vm.addr(ATTESTER_KEY), address(this));
        // Honest seed, issued now.
        _submit(V, uint64(block.timestamp));
    }

    /// @dev One relay an hour (plus the five minutes the hold leaves), every answer held HOLD before it
    /// is relayed. Expected under the documented bound: each step is at most the cap (20%). Actual: the
    /// second step onwards opens on the 40% stale base.
    function test_aFeedKeptAliveHourlyMovesAtMostTheCapPerHour() public {
        uint256 cap = feed.maxDeviationBps();
        uint256 value = V;
        // Step 1, an hour after the seed: the epoch has run its lifetime, the allowance is the cap.
        _advance(1 hours);
        value = value * (10_000 + cap) / 10_000;
        _submit(value, uint64(block.timestamp - HOLD));
        // Steps 2-4: each relayed one hour and five minutes after the previous relay, so the feed has
        // never been silent for a whole hour past its lifetime, yet its allowance reads 2x the cap.
        for (uint256 i; i < 3; ++i) {
            _advance(1 hours + 5 minutes);
            (,, uint256 allowance) = feed.epoch();
            assertLe(allowance, cap, "an hourly-relayed feed must not open its epoch on the stale base");
            // What the code actually lets through: a 40% step.
            uint256 attempt = value * (10_000 + 2 * cap) / 10_000;
            bool accepted = _try(attempt, uint64(block.timestamp - HOLD));
            assertFalse(accepted, "a 40% step was accepted an hour after the last relay");
            // Keep the feed alive either way: the honest cap step is what an hourly relayer sends.
            value = accepted ? attempt : value * (10_000 + cap) / 10_000;
            if (!accepted) _submit(value, uint64(block.timestamp - HOLD));
        }
    }

    /// @dev The same walk expressed as a bound on the end value: four hourly relays may multiply the
    /// feed by at most 1.2^4 = 2.0736 with a 2,000 bps cap.
    function test_fourHourlyRelaysMoveTheFeedAtMostTheCapToTheFourth() public {
        uint256 value = V;
        _advance(1 hours);
        value = value * 12 / 10;
        _submit(value, uint64(block.timestamp - HOLD));
        for (uint256 i; i < 3; ++i) {
            _advance(1 hours + 5 minutes);
            uint256 attempt = value * 14 / 10;
            if (_try(attempt, uint64(block.timestamp - HOLD))) value = attempt;
        }
        (uint256 got,) = feed.latestValue();
        assertLe(got, V * 20_736 / 10_000 + 1, "four hourly relays walked the feed past 1.2^4");
    }

    function _advance(uint256 secs) private {
        vm.warp(block.timestamp + secs);
        vm.roll(block.number + secs / 12);
    }

    function _submit(uint256 figure, uint64 issuedAt) private {
        SwarmFeed.OracleAttestation memory a = _attestation(figure, issuedAt);
        feed.submitAttestation(a, _sign(a));
    }

    function _try(uint256 figure, uint64 issuedAt) private returns (bool ok) {
        SwarmFeed.OracleAttestation memory a = _attestation(figure, issuedAt);
        bytes memory sig = _sign(a);
        try feed.submitAttestation(a, sig) {
            ok = true;
        } catch (bytes memory reason) {
            assertEq(bytes4(reason), SwarmFeed.ExcessDeviation.selector, "refused for another reason");
        }
    }

    function _attestation(uint256 figure, uint64 issuedAt) private returns (SwarmFeed.OracleAttestation memory a) {
        a.requestId = keccak256(abi.encode("request", ++nonce));
        a.chainId = 1;
        a.questionHash = keccak256("question");
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = uint64(block.number - 300);
        a.toBlock = uint64(block.number);
        a.blockHash = keccak256("block");
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = issuedAt;
        a.expiresAt = uint64(block.timestamp + 1 days);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure,
                    a.fromBlock
                ),
                abi.encode(
                    a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

