// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev Unbound leaf (no question prefix) with this test as its relayer, so the suite can sign as the
/// attester. Nothing else differs from the shipped feeds: same _accept, same _allowanceNow.
contract Leaf is SwarmFeed {
    constructor(address attester_, address relayer_, uint256 maxAge_, uint256 cap_)
        SwarmFeed(attester_, relayer_, 1, 3, maxAge_, cap_)
    {}
}

/// @notice The stale base is "earned by a whole hour of silence past the lifetime" (SwarmFeed NatSpec,
/// _allowanceNow). Silence is measured from the attestation's SIGNED issuedAt, which the relayer may
/// hold back by up to maxAge (submitAttestation accepts issuedAt up to maxAge old). A buyer who relays
/// each step with issuedAt 55 minutes old therefore reaches the 2x stale base 65 minutes after relaying,
/// not two hours, and compounds at 1.4 per 65 minutes instead of the documented 1.2 per hour.
contract StaleBaseFromIssuedAtTest is Test {
    uint256 private constant KEY = 0xA11CE;
    Leaf private feed;

    function setUp() public {
        vm.chainId(1);
        vm.warp(10 days);
        vm.roll(1_000_000);
        feed = new Leaf(vm.addr(KEY), address(this), 1 hours, 2_000);
    }

    function test_backdatedIssuedAtEarnsTheStaleBaseWithinOneLifetimeOfTheLastRelay() public {
        uint256 t0 = block.timestamp;
        // Honest value, signed and relayed now.
        _relay("seed", 1 ether, uint64(t0));
        uint256 cap = feed.maxDeviationBps();

        // Step 1 at t0 + 1h: the epoch has run its lifetime, the allowance is the cap. The attacker's
        // attestation was issued 55 minutes ago (held back; still within maxAge, window still recent).
        vm.warp(t0 + 1 hours);
        assertEq(_allowance(), cap, "first step: the cap");
        _relay("step-1", 1.2 ether, uint64(block.timestamp - 55 minutes));

        // 65 minutes after that relay the feed has been kept alive for one lifetime and five minutes.
        // Documented: "a feed anyone keeps alive moves at most the cap per hour however it is driven",
        // so the next epoch must open on the cap. Actual: silence is counted from the backdated issuedAt,
        // the value has been "stale" for a whole hour, and the stale base (2x the cap) is granted.
        vm.warp(block.timestamp + 65 minutes);
        // The walk takes it: 1.2 x 1.4 = 1.68 in two hours and five minutes (the cap per hour allows 1.44).
        bool accepted = _tryRelay("step-2", 1.68 ether, uint64(block.timestamp - 55 minutes));
        assertFalse(accepted, "1.68 after two steps 65 minutes apart exceeds the cap per hour; must be refused");
        assertEq(_allowance(), cap, "65 minutes after a relay the allowance must still be the cap");
    }

    function _tryRelay(bytes32 id, uint256 figure, uint64 issuedAt) private returns (bool ok) {
        SwarmFeed.OracleAttestation memory a = _build(id, figure, issuedAt);
        (ok,) = address(feed).call(abi.encodeCall(feed.submitAttestation, (a, _sign(a))));
    }

    function _allowance() private view returns (uint256 allowance) {
        (,, allowance) = feed.epoch();
    }

    function _relay(bytes32 id, uint256 figure, uint64 issuedAt) private {
        SwarmFeed.OracleAttestation memory a = _build(id, figure, issuedAt);
        feed.submitAttestation(a, _sign(a));
    }

    function _build(bytes32 id, uint256 figure, uint64 issuedAt)
        private
        view
        returns (SwarmFeed.OracleAttestation memory a)
    {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = keccak256("q");
        a.answerType = 3;
        a.answer = bytes("x");
        a.figure = figure;
        a.fromBlock = uint64(block.number - 600);
        a.toBlock = uint64(block.number - 1);
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("p");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = issuedAt;
        a.expiresAt = issuedAt + 1 days;
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure,
                    a.fromBlock
                ),
                abi.encode(
                    a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

