pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";

/// @dev A question-bound feed with the PriceFeed policy (one-hour life, 2,000 bps cap, 300..1200-block
/// window, data chain 1) and an attester key the test holds. Relayer zero: SwarmRelay admits everyone
/// anyway, so a permissionless feed is the same trust.
contract WalkFeed is SwarmFeed {
    bytes private constant PREFIX = '{"answerType":"uint256","chainId":1,"question":"IMD/ETH","v":1,"window":{"fromBlock":';

    constructor(address attester_) SwarmFeed(attester_, address(0), 1, 3, 1 hours, 2000) {}

    function questionPolicy() internal pure override returns (bytes memory, uint64, uint64) {
        return (PREFIX, 300, 1_200);
    }
}

/// @notice SwarmFeed._allowanceNow measures the "whole hour of silence" that earns the stale base
/// (2x the cap) from the SIGNED issuedAt, but the relayer chooses when to relay: the window-recency
/// bound (WindowTooOld) lets an attestation land up to maxAge after its window closed, about 57
/// minutes after it was signed. A buyer who holds each step for 57 minutes before relaying it opens
/// every epoch on the stale base 62 minutes after the previous acceptance, and the walk compounds at
/// 1.4 per 62 minutes rather than the committed 1.2 per hour.
contract DelayedRelayWalkTest is Test {
    uint256 private constant KEY = 0xA11CE;
    uint256 private constant V = 3.7e15; // wei of ETH per 1e18 IMD, about the live figure
    uint256 private constant SIGN_LAG = 130; // the real attestation e2c85027: signed 2m10s after request

    WalkFeed private feed;
    uint256 private nonce;

    function setUp() public {
        vm.chainId(1); // the recency bound applies only on the data chain, which mainnet is
        vm.roll(1_000_000);
        vm.warp(12 * 1_000_000);
        feed = new WalkFeed(vm.addr(KEY));
    }

    function test_holdingEachStepFiftySevenMinutesEarnsTheStaleBaseEveryHour() public {
        // An honest value, signed and relayed now.
        _relay(V, uint64(block.number), uint64(block.timestamp));
        uint256 cap = feed.maxDeviationBps();
        uint256 value = V;

        // Step 1, one lifetime later: the cap, as committed. The attestation was bought 57 minutes ago
        // (its window closed exactly 300 blocks ago, the last block WindowTooOld admits).
        _advance(3600 + 12);
        value = value * (10_000 + cap) / 10_000;
        _relayHeld(value);

        // Every later step: 62 minutes and 10 seconds after the previous ACCEPTANCE, the stored epoch has
        // expired and the signed issuedAt of the held attestation is two whole hours old. PARAMETERS and
        // the SwarmFeed docstring promise a feed anyone keeps alive moves at most the cap per hour; the
        // allowance read here must therefore still be the cap, and a 1.4x step must be refused.
        for (uint256 i = 2; i <= 5; ++i) {
            _advance(3600 + SIGN_LAG);
            (,, uint256 allowance) = feed.epoch();
            assertEq(allowance, cap, "62 minutes after the last acceptance the allowance is the cap, not 2x");
            uint256 wide = value * (10_000 + cap * feed.STALE_DEVIATION_MULTIPLE()) / 10_000;
            _expectHeldRefused(wide);
            value = value * (10_000 + cap) / 10_000;
            _relayHeld(value);
        }
    }

    // --- helpers -------------------------------------------------------------------------------

    function _advance(uint256 seconds_) private {
        vm.warp(block.timestamp + seconds_);
        vm.roll(block.timestamp / 12);
    }

    /// @dev An attestation whose window closed 300 blocks ago (an hour; the recency limit) and that the
    /// attester signed SIGN_LAG seconds after that: bought 57 minutes ago, relayed now.
    function _relayHeld(uint256 figure) private {
        uint64 toBlock = uint64(block.number - 300);
        uint64 issuedAt = uint64(toBlock * 12 + SIGN_LAG);
        _relay(figure, toBlock, issuedAt);
    }

    function _expectHeldRefused(uint256 figure) private {
        uint64 toBlock = uint64(block.number - 300);
        uint64 issuedAt = uint64(toBlock * 12 + SIGN_LAG);
        (SwarmFeed.OracleAttestation memory a, bytes memory sig) = _signed(figure, toBlock, issuedAt);
        vm.expectRevert(SwarmFeed.ExcessDeviation.selector);
        feed.submitAttestation(a, sig);
    }

    function _relay(uint256 figure, uint64 toBlock, uint64 issuedAt) private {
        (SwarmFeed.OracleAttestation memory a, bytes memory sig) = _signed(figure, toBlock, issuedAt);
        feed.submitAttestation(a, sig);
        (uint256 got, uint64 at) = feed.latestValue();
        assertEq(got, figure);
        assertEq(at, issuedAt);
    }

    function _signed(uint256 figure, uint64 toBlock, uint64 issuedAt)
        private
        returns (SwarmFeed.OracleAttestation memory a, bytes memory sig)
    {
        a.requestId = keccak256(abi.encode("request", ++nonce));
        a.chainId = 1;
        a.fromBlock = toBlock - 600;
        a.toBlock = toBlock;
        a.questionHash = feed.expectedQuestionHash(a.fromBlock, a.toBlock);
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.blockHash = keccak256(abi.encode("block", toBlock));
        a.panelJobId = keccak256(abi.encode("panel", nonce));
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 20;
        a.issuedAt = issuedAt;
        a.expiresAt = issuedAt + 1 days; // the live attestation's TTL
        bytes32 structHash = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure,
                    a.fromBlock
                ),
                abi.encode(
                    a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), structHash));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(KEY, digest);
        sig = abi.encodePacked(r, s, v);
    }
}
